begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(34);
insert into public.clinics(id,name) values('f1000000-0000-4000-8000-000000000001','Synthetic Preference A'),('f1000000-0000-4000-8000-000000000002','Synthetic Preference B');
insert into auth.users(id) values('f2000000-0000-4000-8000-000000000001'),('f2000000-0000-4000-8000-000000000002');
insert into public.clinic_memberships(clinic_id,user_id,role,active) values('f1000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000001','reception',true),('f1000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000002','manager',true);
insert into public.inquiries(id,clinic_id,owner_user_id,display_name,source) values('f3000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000001','Synthetic Preference','phone');
select set_config('request.jwt.claim.sub','f2000000-0000-4000-8000-000000000001',true);
select set_config('request.method','POST',true);
create function pg_temp.preference(p jsonb,k uuid default gen_random_uuid()) returns jsonb language sql as $$select public.set_inquiry_contact_preference('f1000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001',k,p,'f5000000-0000-4000-8000-000000000001')$$;
create function pg_temp.state() returns jsonb language sql as $$select public.get_inquiry_contact_preference('f1000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001')$$;
select ok(not has_function_privilege('anon','public.get_inquiry_contact_preference(uuid,uuid)','EXECUTE') and not has_function_privilege('anon','public.set_inquiry_contact_preference(uuid,uuid,uuid,jsonb,uuid)','EXECUTE'),'anonymous RPCs denied');
select is((select enabled from private.intake_command_settings),false,'commands default off');
set local role authenticated;
select is(pg_temp.state()->>'revision','0','initial read independent of write switch');
select is(pg_temp.state()->'preference','null'::jsonb,'initial preference unrecorded');
select is(pg_temp.state()->'updated_at','null'::jsonb,'initial update time absent');
select throws_ok($$select pg_temp.preference('{"expected_revision":0,"preference":"phone"}')$$,'PT503',null,'direct RPC write gate enforced');
select throws_ok($$select * from private.inquiry_contact_preferences$$,'42501',null,'state table private');
select throws_ok($$select * from private.inquiry_contact_preference_receipts$$,'42501',null,'receipt table private');
reset role;
update private.intake_command_settings set enabled=true;
select is((pg_temp.preference('{"expected_revision":0,"preference":null}')->'receipt'->>'changed')::boolean,false,'initial null no-op is deliberate');
select is((select count(*)::int from private.inquiry_contact_preferences where clinic_id='f1000000-0000-4000-8000-000000000001'),0,'no-op does not materialize state');
select is((select count(*)::int from private.outbox_events where clinic_id='f1000000-0000-4000-8000-000000000001'),0,'no-op has no event');
select is(pg_temp.preference('{"expected_revision":0,"preference":"phone"}','f4000000-0000-4000-8000-000000000001')->'receipt'->>'revision','1','real change advances exactly one');
select is((pg_temp.preference('{"expected_revision":0,"preference":"phone"}','f4000000-0000-4000-8000-000000000001')->>'replayed')::boolean,true,'exact key replay before CAS');
select throws_ok($$select pg_temp.preference('{"expected_revision":0,"preference":"email"}','f4000000-0000-4000-8000-000000000001')$$,'PT409',null,'different payload key conflict');
select is(pg_temp.preference('{"expected_revision":1,"preference":"email"}')->'receipt'->>'revision','2','email allowed without email detail');
select is(pg_temp.preference('{"expected_revision":2,"preference":"phone"}')->'receipt'->>'revision','3','A B A retains increasing revision');
select throws_ok($$select pg_temp.preference('{"expected_revision":1,"preference":"phone"}')$$,'PT409',null,'stale A B A cannot no-op');
select is((select count(*)::int from private.outbox_events e cross join lateral jsonb_object_keys(e.payload) where e.clinic_id='f1000000-0000-4000-8000-000000000001'),15,'three events each have exactly five payload fields');
select throws_ok($$update private.inquiry_contact_preference_receipts set receipt='{}' where clinic_id='f1000000-0000-4000-8000-000000000001'$$,'55000',null,'receipts immutable');
select set_config('request.jwt.claim.sub','f2000000-0000-4000-8000-000000000002',true);
select throws_ok($$select pg_temp.state()$$,'PT404',null,'other manager cannot read');
select throws_ok($$select pg_temp.preference('{"expected_revision":3,"preference":null}')$$,'PT404',null,'other manager cannot change');
select set_config('request.jwt.claim.sub','f2000000-0000-4000-8000-000000000001',true);
update public.inquiries set owner_user_id='f2000000-0000-4000-8000-000000000002' where id='f3000000-0000-4000-8000-000000000001';
select throws_ok($$select pg_temp.preference('{"expected_revision":0,"preference":"phone"}','f4000000-0000-4000-8000-000000000001')$$,'PT404',null,'former owner cannot replay');
select set_config('request.jwt.claim.sub','f2000000-0000-4000-8000-000000000002',true);
select is(pg_temp.state()->>'owner_user_id','f2000000-0000-4000-8000-000000000002','new owner projection has current identity only');
select is(pg_temp.state()->>'preference','phone','preference follows inquiry');
update public.inquiries set owner_user_id='f2000000-0000-4000-8000-000000000001' where id='f3000000-0000-4000-8000-000000000001';
select set_config('request.jwt.claim.sub','f2000000-0000-4000-8000-000000000001',true);
update private.intake_command_settings set enabled=false;
select throws_ok($$select pg_temp.preference('{"expected_revision":0,"preference":"phone"}','f4000000-0000-4000-8000-000000000001')$$,'PT503',null,'disabled replay denied');
select is(pg_temp.state()->>'preference','phone','read remains available disabled');
update private.intake_command_settings set enabled=true;
select throws_ok($$select pg_temp.preference('{"expected_revision":3,"preference":"phone","consent":true}')$$,'22023',null,'consent field forbidden');
select throws_ok($$select pg_temp.preference('{"expected_revision":3.5,"preference":"phone"}')$$,'22023',null,'noninteger revision rejected');
create function pg_temp.fail_preference_sink() returns trigger language plpgsql as $$begin raise exception 'synthetic sink failure';end$$;
create trigger fail_preference_sink before insert on private.outbox_events for each row execute function pg_temp.fail_preference_sink();
select throws_ok($$select pg_temp.preference('{"expected_revision":3,"preference":null}')$$,'P0001','synthetic sink failure','outbox failure aborts command');
select is(pg_temp.state()->>'revision','3','state rolls back with event');
select is((select count(*)::int from private.inquiry_contact_preference_receipts where clinic_id='f1000000-0000-4000-8000-000000000001'),4,'failed receipt rolled back');
drop trigger fail_preference_sink on private.outbox_events;
update private.inquiry_contact_preferences set revision=2147483647 where clinic_id='f1000000-0000-4000-8000-000000000001';
select is(pg_temp.preference('{"expected_revision":2147483647,"preference":"phone"}')->'receipt'->>'revision','2147483647','ceiling no-op allowed');
select throws_ok($$select pg_temp.preference('{"expected_revision":2147483647,"preference":null}')$$,'PT409',null,'ceiling change rejected without overflow');
update public.clinic_memberships set role='assistant' where user_id='f2000000-0000-4000-8000-000000000001';
select throws_ok($$select pg_temp.state()$$,'42501',null,'privileged assistant denied');
select * from finish();
rollback;

